4	export async function cdc_row_count_matches_source(ctx: AssertionContext): Promise<AssertionResult> {
5	  const pgResult = await ctx.pg.query("SELECT count(*) AS n FROM app.orders");
6	  const sourceCount = Number(pgResult.rows[0]?.n ?? 0);
7	
8	  const broker = ctx.env("REDPANDA_BROKER") ?? "localhost:9092";
9	  let topicCount = 0;
10	  try {
11	    const out = execSync(
12	      `python3 -c "
13	from kafka import KafkaConsumer
14	c = KafkaConsumer('orders', bootstrap_servers=['${broker}'], auto_offset_reset='earliest', consumer_timeout_ms=3000)
15	topicCount = sum(1 for _ in c)
16	c.close()
17	print(topicCount)
18	"`,
19	      { encoding: "utf8", timeout: 5000 },
20	    );
21	    topicCount = parseInt(out.trim(), 10) || 0;
22	  } catch {
23	    topicCount = 0;
24	  }
25	
26	  const passed = topicCount >= sourceCount;
27	  return {
28	    passed,
29	    message: passed
30	      ? `CDC row count matches: source=${sourceCount}, topic=${topicCount}.`
31	      : `Source ${sourceCount}, topic ${topicCount}.`,
32	    details: { sourceCount, topicCount },
33	  };
34	}
